#!/usr/bin/python
import os
import tempfile
import BaseHTTPServer
import SocketServer

BASE = os.path.dirname(os.path.abspath(__file__))
RECEIVED = os.path.join(BASE, 'received')
STAGING = os.path.join(BASE, '.staging')
MAX_BODY = 65536

class ThreadedHTTPServer(SocketServer.ThreadingMixIn, BaseHTTPServer.HTTPServer):
    daemon_threads = True
    allow_reuse_address = True

class Handler(BaseHTTPServer.BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'

    def bodyless_response(self, code, message=None):
        if message is None:
            self.send_response(code)
        else:
            self.send_response(code, message)
        self.send_header('Content-Length', '0')
        self.send_header('Connection', 'close')
        self.end_headers()
        self.close_connection = 1

    def not_found(self):
        self.bodyless_response(404, 'Not Found')

    def do_GET(self):
        self.not_found()

    def do_HEAD(self):
        self.not_found()

    def do_PUT(self):
        self.not_found()

    def do_DELETE(self):
        self.not_found()

    def do_POST(self):
        if self.path != '/upload':
            self.not_found()
            return

        transfer_encoding = self.headers.get('Transfer-Encoding')
        if transfer_encoding and transfer_encoding.lower() != 'identity':
            self.bodyless_response(501, 'Transfer Encoding Not Supported')
            return

        value = self.headers.get('Content-Length')
        if value is None:
            self.bodyless_response(411, 'Length Required')
            return
        try:
            length = long(value)
        except (TypeError, ValueError):
            self.bodyless_response(400, 'Bad Content-Length')
            return
        if length < 0:
            self.bodyless_response(400, 'Bad Content-Length')
            return
        if length > MAX_BODY:
            self.bodyless_response(413, 'Request Entity Too Large')
            return

        fd = None
        stream = None
        temp_path = None
        completed = False
        try:
            fd, temp_path = tempfile.mkstemp(prefix='upload-', dir=STAGING)
            stream = os.fdopen(fd, 'wb')
            fd = None
            remaining = length
            while remaining:
                chunk = self.rfile.read(min(8192, remaining))
                if not chunk:
                    raise IOError('request body ended early')
                stream.write(chunk)
                remaining -= len(chunk)
            stream.flush()
            os.fsync(stream.fileno())
            stream.close()
            stream = None

            name = os.path.basename(temp_path) + '.bin'
            final_path = os.path.join(RECEIVED, name)
            os.link(temp_path, final_path)
            os.unlink(temp_path)
            temp_path = None
            completed = True
        except:
            self.close_connection = 1
        finally:
            if stream is not None:
                try:
                    stream.close()
                except:
                    pass
            elif fd is not None:
                try:
                    os.close(fd)
                except:
                    pass
            if temp_path is not None:
                try:
                    os.unlink(temp_path)
                except:
                    pass

        if completed:
            self.bodyless_response(200, 'OK')

def prepare_directories():
    if not os.path.isdir(RECEIVED):
        os.mkdir(RECEIVED, 0755)
    if not os.path.isdir(STAGING):
        os.mkdir(STAGING, 0700)
    for name in os.listdir(STAGING):
        path = os.path.join(STAGING, name)
        try:
            if os.path.isfile(path):
                os.unlink(path)
        except:
            pass

if __name__ == '__main__':
    prepare_directories()
    server = ThreadedHTTPServer(('', 8080), Handler)
    server.serve_forever()
ANTRIEB_SERVER_EOF
